window.RA_DATA = window.RA_DATA || {};
window.RA_DATA.lines = [
  { id: "can-s1", kind: "scene", book_id: "cantico-espiritual", place_ids: ["es-carmelitas-segovia"], location: "Composition, 1577–78", location_zh: "写作经过，1577–78 年", text_en: "Kidnapped by friars opposed to his reforms, John is shut for nine months in a tiny cell in the Toledo priory, flogged and half-starved. There, without paper, he composes the first thirty-one stanzas of the Canticle, a dialogue between the soul as bride and her hidden beloved, and memorises them. In August 1578 he escapes by a rope of knotted blankets.", text_zh: "反对他改革的修士们把十字若望绑走，关在托莱多修院一间狭小的囚室里九个月，鞭打他、几乎不给饭吃。他没有纸，就在那里默默写出《灵歌》的前三十一节——作为新娘的灵魂与隐藏的爱人之间的对答，全凭记忆记下。1578 年 8 月，他用打结的毯子结成绳索逃了出去。", highlight_en: ["thirty-one stanzas"], highlight_zh: ["前三十一节"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Spiritual_Canticle" },
  { id: "dq-s2", kind: "scene", book_id: "don-quixote", place_ids: ["es-toboso"], location: "Part II, chapter 9", location_zh: "下卷第九章", text_en: "At midnight Don Quixote and Sancho ride into the sleeping village of El Toboso to find Dulcinea's palace. Sancho, who has never seen her, leads him through dark streets among barking dogs until they come up against a great building: 'It's the church we've run into, Sancho.'", text_zh: "半夜，堂吉诃德和桑丘骑马进入沉睡的托博索村，寻找杜尔西内娅的宫殿。从没见过她的桑丘领着他在漆黑的街上、在一片狗叫声中摸来摸去，最后撞上一座大建筑——“桑丘，我们撞上的是教堂。”", highlight_en: ["It's the church we've run into"], highlight_zh: ["我们撞上的是教堂"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/Don_Quijote_de_la_Mancha" },
  { id: "som-s1", kind: "scene", book_id: "sombrero-de-tres-picos", place_ids: ["es-guadix"], location: "Chapters 20–36", location_zh: "第二十至三十六章", text_en: "While the miller Tío Lucas is lured into town on a false summons, the corregidor, in his three-cornered hat, steals into the mill to court Frasquita, falls in the millrace and is left to dry in Lucas's bed. Lucas returns, thinks the worst, puts on the corregidor's clothes and sets off to pay the corregidor's wife a visit in turn.", text_zh: "磨坊主卢卡斯大叔被一纸假传票骗进城，戴三角帽的地方长官趁机溜进磨坊去勾引弗拉斯基塔，却掉进水渠，只好脱下湿衣服躺在卢卡斯的床上。卢卡斯回来，以为最坏的事发生了，便穿上长官的衣服，出发去回访长官夫人。", highlight_en: ["three-cornered hat"], highlight_zh: ["三角帽"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/El_sombrero_de_tres_picos_(novela)" },
  { id: "miau-s1", kind: "scene", book_id: "miau", place_ids: ["es-aduana"], location: "Throughout", location_zh: "全书", text_en: "Ramón Villaamil, a conscientious clerk of the Ministry of Finance, has been dismissed two months before he would have earned his pension. Day after day he walks to the ministry, buttonholes officials and writes petitions and reform plans, while his family keeps up appearances on credit and his grandson Luis has visions in which God tells him his grandfather will never be reinstated.", text_zh: "拉蒙·比利亚米尔是财政部一名尽职的职员，在离领退休金只差两个月时被辞退。他天天走到部里，拦住官员，写请愿书和改革方案；家里人靠赊账撑着体面，孙子路易斯则在幻觉中听见上帝告诉他，爷爷永远也复不了职。", highlight_en: ["Ministry of Finance"], highlight_zh: ["财政部"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/Miau_(novela)" },
  { id: "pdu-s1", kind: "scene", book_id: "pazos-de-ulloa", place_ids: ["es-pardo-bazan-house"], location: "Chapters 1–3", location_zh: "第一至三章", text_en: "Julián, a timid young priest, rides into the Galician hills to become chaplain at the manor of the Marquis of Ulloa. He finds a ruined house run by the steward Primitivo, whose daughter Sabel is the marquis's mistress, and at supper watches the men make Sabel's small son Perucho drunk on wine for fun.", text_zh: "胆小的年轻神父胡利安骑马进入加利西亚山区，到乌略亚侯爵的府邸当家庭神父。他发现府邸破败不堪，由管家普里米蒂沃把持，管家的女儿萨贝尔是侯爵的情妇；晚饭时，他眼看着男人们为了取乐，把萨贝尔的小儿子佩鲁乔灌醉。", highlight_en: ["Galician hills"], highlight_zh: ["加利西亚山区"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_House_of_Ulloa" },
  { id: "sol-s1", kind: "scene", book_id: "solitud", place_ids: ["es-lescala"], location: "Throughout", location_zh: "全书", text_en: "Mila follows her idle husband Matias up to the hermitage of Sant Ponç, high in the mountains, where he is to be keeper. Alone among the rocks and the mountain people, she restores the chapel, befriends the wise old shepherd Gaietà, and survives an attack by the brutal Ànima; at the end she walks down the mountain alone.", text_zh: "米拉跟着懒散的丈夫马蒂亚斯上山，来到高山上的圣蓬斯隐修院，丈夫要在那里当看守。她独自面对岩石和山里人，修整小教堂，和睿智的老牧人盖埃塔成了朋友，又挺过了粗野的阿尼马的侵害；最后，她一个人走下了山。", highlight_en: ["hermitage of Sant Ponç"], highlight_zh: ["圣蓬斯隐修院"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/Solitud" },
  { id: "zal-s2", kind: "scene", book_id: "zalacain", place_ids: ["es-itzea"], location: "Throughout", location_zh: "全书", text_en: "Martín Zalacaín, a poor boy from a Basque border town raised by the old smuggler Tellagorri, grows up to run contraband and carry messages through both lines in the Third Carlist War of the 1870s, in love with the sister of the rich Carlos de Ohando, his lifelong enemy.", text_zh: "马丁·萨拉凯因是巴斯克边境小镇的穷孩子，由老走私贩特利亚戈里带大。长大后，他在 19 世纪 70 年代的第三次卡洛斯战争中贩私货、穿越两军防线送信，爱上了宿敌、富家子卡洛斯·德奥安多的妹妹。", highlight_en: ["Third Carlist War"], highlight_zh: ["第三次卡洛斯战争"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/Zalaca%C3%ADn_el_aventurero" },
  { id: "sha-s1", kind: "scene", book_id: "shanti-andia", place_ids: ["es-itzea"], location: "Throughout", location_zh: "全书", text_en: "An old sea captain looks back on his boyhood in the Basque fishing town of Lúzaro, on his voyages, and on the mystery of his uncle Juan de Aguirre, mourned as dead, who returns at last as a stranger and leaves a manuscript telling of slave ships and a changed name.", text_zh: "一位老船长回忆自己在巴斯克渔港卢萨罗的童年、自己的航海生涯，以及叔叔胡安·德阿吉雷之谜：这位叔叔早被当作死人办了丧事，最后却以陌生人的身份回来，留下一份手稿，讲述贩奴船和他改换的姓名。", highlight_en: ["Lúzaro"], highlight_zh: ["卢萨罗"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/Las_inquietudes_de_Shanti_And%C3%ADa" },
  { id: "pla-s1", kind: "scene", book_id: "platero-y-yo", place_ids: ["es-moguer"], location: "Chapters 1, 132–135", location_zh: "第一章、第一三二至一三五章", text_en: "'Platero is small, furry, soft', the book begins: a little donkey so soft outside he seems made of cotton. The poet walks him through the seasons of Moguer, its children, beggars, feast days and fields. Platero dies, and is buried under the round pine at Fuentepiña.", text_zh: "“小银个子小小的，毛茸茸的，软软的”，书这样开头：一头摸上去软得像棉花做的小毛驴。诗人牵着它走过莫格尔的四季，看孩子、乞丐、节日和田野。后来小银死了，埋在丰特皮尼亚那棵圆顶松下。", highlight_en: ["Fuentepiña"], highlight_zh: ["丰特皮尼亚"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Platero_and_I" },
  { id: "rom-s1", kind: "scene", book_id: "romancero-gitano", place_ids: ["es-huerta-san-vicente"], location: "'Romance sonámbulo'", location_zh: "《梦游人谣》", text_en: "'Green, how I want you green': a wounded smuggler, pursued by the Civil Guard, climbs to the balcony of the gypsy girl who waited for him, and finds her drowned in the cistern, floating green in the moonlight. The Gypsy Ballads made Lorca the most famous poet in Spain.", text_zh: "“绿啊，我多么爱你，绿”：一个受伤的走私者被国民警卫队追捕，爬上那个一直等着他的吉卜赛姑娘的阳台，却发现她已淹死在蓄水池里，在月光下泛着绿色。《吉卜赛谣曲集》让洛尔迦成了西班牙最有名的诗人。", highlight_en: ["Green, how I want you green"], highlight_zh: ["绿啊，我多么爱你，绿"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Gypsy_Ballads" },
  { id: "bds-s1", kind: "scene", book_id: "bodas-de-sangre", place_ids: ["es-cortijo-fraile"], location: "Acts II–III", location_zh: "第二至三幕", text_en: "On her wedding day the Bride rides off with Leonardo, her old love, now married to her cousin. The Groom and his kinsmen hunt them through a moonlit forest, where the Moon and a beggar woman who is Death watch; the two men kill each other, and the women are left with their grief.", text_zh: "婚礼当天，新娘和旧情人莱昂纳多骑马私奔，莱昂纳多已娶了她的表妹。新郎带着族人追进月光下的森林，月亮和化身乞妇的死神在一旁看着；两个男人互相杀死，留下女人们承受悲痛。", highlight_en: ["moonlit forest"], highlight_zh: ["月光下的森林"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Blood_Wedding" },
  { id: "nada-s1", kind: "scene", book_id: "nada-laforet", place_ids: ["es-aribau"], location: "Part I, chapter 1", location_zh: "第一部第一章", text_en: "Arriving by a late train in the autumn of 1940, Andrea carries her suitcase through the night to the flat on Calle de Aribau she remembers from childhood. The door is opened by a ghostly grandmother, and inside she finds a filthy, crowded home where her uncles Juan and Román and the others quarrel, starve and frighten one another.", text_zh: "1940 年秋，安德烈娅坐晚班火车到达，拎着箱子穿过夜色，来到她童年记忆里阿里鲍街的那套公寓。开门的是幽灵般的外婆，屋里又脏又挤，胡安和罗曼两个舅舅和其他人整天争吵、挨饿、互相恐吓。", highlight_en: ["Calle de Aribau"], highlight_zh: ["阿里鲍街"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Nada_(novel)" },
  { id: "sca-s1", kind: "scene", book_id: "sombra-del-cipres", place_ids: ["es-avila"], location: "Part I", location_zh: "第一部", text_en: "Pedro, an orphan, is sent to board in Ávila with Don Mateo Lesmes, a teacher who preaches that one should own and love nothing, since every loss hurts. Pedro's only friend Alfredo dies young of tuberculosis, and the boy takes the lesson into a life at sea, until love tests it.", text_zh: "孤儿佩德罗被送到阿维拉，寄宿在教师马特奥·莱斯梅斯先生家。这位先生宣扬人不该拥有、也不该爱任何东西，因为每一次失去都会痛。佩德罗唯一的朋友阿尔弗雷多年纪轻轻死于肺结核，他便带着这条教训去航海，直到爱情来考验它。", highlight_en: ["Ávila"], highlight_zh: ["阿维拉"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/La_sombra_del_cipr%C3%A9s_es_alargada" },
  { id: "chm-s1", kind: "scene", book_id: "cinco-horas-con-mario", place_ids: ["es-valladolid"], location: "Throughout", location_zh: "全书", text_en: "In March 1966, after a heart attack has killed her husband Mario, a liberal schoolteacher and writer, Carmen sits up alone with his body through the night. For five hours she talks to the dead man, reproaching him for his ideals, his poverty and his books, until her own confession slips out.", text_zh: "1966 年 3 月，丈夫马里奥——一位思想开明的中学教师和作家——死于心脏病。卡门独自守着他的遗体过夜，五个小时里一直对着死者说话，数落他的理想、他的清贫和他的书，直到她自己的秘密也说了出来。", highlight_en: ["five hours"], highlight_zh: ["五个小时"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Five_Hours_with_Mario" },
  { id: "col-s1", kind: "scene", book_id: "la-colmena", place_ids: ["es-glorieta-bilbao"], location: "Chapter 1", location_zh: "第一章", text_en: "One winter afternoon in 1942 in Doña Rosa's café, hungry writers, widows, moneylenders and policemen sit over cheap coffee while the fat owner insults her waiters and patrols the tables. The penniless poet Martín Marco is thrown out for not paying. Some three hundred characters pass through the novel's three days in Madrid.", text_zh: "1942 年冬天的一个下午，在罗莎太太的咖啡馆里，饥饿的作家、寡妇、放债人和警察守着廉价咖啡坐着，胖老板娘一边骂侍者一边在桌间巡视。身无分文的诗人马丁·马尔科因为付不起钱被赶了出去。小说三天的马德里里，约有三百个人物来来去去。", highlight_en: ["Doña Rosa's café"], highlight_zh: ["罗莎太太的咖啡馆"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Hive_(Cela_novel)" },
  { id: "req-s1", kind: "scene", book_id: "requiem-campesino", place_ids: ["es-chalamera"], location: "Throughout", location_zh: "全书", text_en: "In the sacristy, the old priest Mosén Millán waits to say a requiem mass a year after the death of Paco 'of the mill', whom he baptised and married. Nobody comes but the three rich men of the village. Remembering, he admits to himself that in 1936 he told the Falangists where Paco was hiding, and watched them shoot him.", text_zh: "在圣器室里，老神父莫森·米扬等着为“磨坊的帕科”做周年安魂弥撒，帕科是他亲自施洗、证婚的。来的只有村里的三个富人。在回忆里，他向自己承认：1936 年，是他把帕科的藏身处告诉了长枪党，然后眼看着他们枪杀了他。", highlight_en: ["Mosén Millán"], highlight_zh: ["莫森·米扬"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Requiem_for_a_Spanish_Peasant" },
  { id: "cip-s1", kind: "scene", book_id: "cipreses-creen-en-dios", place_ids: ["es-girona"], location: "Throughout", location_zh: "全书", text_en: "Ignacio Alvear, son of a modest Catholic family in Girona, leaves the seminary, works in a bank and studies law as the Second Republic divides his city between left and right, believers and anticlericals, until July 1936 brings the uprising and killing to its streets.", text_zh: "赫罗纳一个普通天主教家庭的儿子伊格纳西奥·阿尔韦亚尔离开神学院，在银行工作，又读法律。第二共和国把他的城市撕裂成左派和右派、信徒和反教权者，直到 1936 年 7 月，叛乱和杀戮来到了这里的街头。", highlight_en: ["July 1936"], highlight_zh: ["1936 年 7 月"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/Los_cipreses_creen_en_Dios" },
  { id: "jar-s1", kind: "scene", book_id: "el-jarama", place_ids: ["es-viveros"], location: "Throughout", location_zh: "全书", text_en: "One hot Sunday in August, eleven young people from Madrid spend the day by the Jarama, swimming, eating and flirting, while locals drink and talk in Mauricio's inn. As darkness falls Luci, one of the girls, goes into the river and drowns; the police come, and the friends go back to the city on the last train.", text_zh: "八月一个炎热的星期天，十一个马德里年轻人在哈拉马河边待了一整天，游泳、吃喝、打情骂俏，当地人则在毛里西奥的酒馆里喝酒聊天。天黑时，姑娘露西下河游泳，淹死了；警察来了，朋友们坐末班火车回城。", highlight_en: ["Luci"], highlight_zh: ["露西"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/El_Jarama" },
  { id: "ev-s1", kind: "scene", book_id: "entre-visillos", place_ids: ["es-bandos-salamanca"], location: "Throughout", location_zh: "全书", text_en: "In a provincial city in the 1950s, the young women of good families spend their days at the casino, the cathedral and the window, waiting for husbands. Pablo Klein, a German teacher new at the school, encourages sixteen-year-old Natalia, who keeps a diary, to want something else.", text_zh: "20 世纪 50 年代的一座外省城市里，好人家的年轻姑娘们整天泡在俱乐部、大教堂和窗前，等着嫁人。刚来学校教德语的帕布罗·克莱因鼓励记日记的十六岁女孩娜塔莉娅去追求别的东西。", highlight_en: ["Pablo Klein"], highlight_zh: ["帕布罗·克莱因"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Entre_visillos" },
  { id: "cda-s1", kind: "scene", book_id: "cuarto-de-atras", place_ids: ["es-bandos-salamanca"], location: "Throughout", location_zh: "全书", text_en: "On a sleepless night in her Madrid flat, a woman writer is visited by a mysterious man in a black hat who has come to interview her. As they talk until dawn she remembers her childhood in Salamanca, the back room where she was free to play, the war and the postwar years, and the book she has never written.", text_zh: "一个失眠的夜里，一位女作家在马德里的公寓里迎来一个戴黑帽子的神秘男人，说是来采访她。两人一直聊到天亮，她想起在萨拉曼卡的童年、那间可以随意玩耍的后屋、战争和战后岁月，还有那本她一直没写出来的书。", highlight_en: ["the back room"], highlight_zh: ["后屋"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/El_cuarto_de_atr%C3%A1s" },
  { id: "pdd-s1", kind: "scene", book_id: "placa-del-diamant", place_ids: ["es-placa-diamant"], location: "Chapters 1, 49", location_zh: "第一章、第四十九章", text_en: "At the dance in the Plaça del Diamant during the festival of Gràcia, shy young Natàlia meets Quimet, who tells her she will be his wife within a year and calls her Colometa. Through the Republic, the war, his death and hunger she survives; at the end she returns to the square and lets out a scream that has been inside her for years.", text_zh: "格拉西亚节日期间，在钻石广场的舞会上，害羞的娜塔莉娅认识了基梅特。他说一年之内她就会嫁给他，还叫她“科洛梅塔”。经历了共和国、战争、丈夫战死和饥饿，她活了下来；最后她回到广场，喊出了在心里憋了多年的那一声。", highlight_en: ["Colometa"], highlight_zh: ["科洛梅塔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Time_of_the_Doves" },
  { id: "sav-s1", kind: "scene", book_id: "caso-savolta", place_ids: ["es-barcelona"], location: "Throughout", location_zh: "全书", text_en: "Barcelona, 1917–1919: as anarchists and hired gunmen kill each other in the streets, the arms manufacturer Savolta is shot at his New Year's Eve party. Javier Miranda, a young clerk dazzled by the firm's charming French manager Lepprince, tells the story years later in testimony to a New York court.", text_zh: "1917 到 1919 年的巴塞罗那，无政府主义者和受雇的枪手在街头互相残杀，军火商萨沃尔塔在自家跨年舞会上被枪杀。年轻职员哈维尔·米兰达被公司迷人的法国经理勒普林斯迷住，多年后在纽约法庭的证词里讲述了这一切。", highlight_en: ["New Year's Eve party"], highlight_zh: ["跨年舞会"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Truth_about_the_Savolta_Case" },
  { id: "cdp-s1", kind: "scene", book_id: "ciudad-de-los-prodigios", place_ids: ["es-ciutadella"], location: "Chapter 1", location_zh: "第一章", text_en: "In 1887 the teenage Onofre Bouvila arrives in Barcelona from a mountain village with nothing, and finds work on the building site of the coming Universal Exposition by handing out anarchist leaflets to the workers and selling them hair tonic. From there he rises, by fraud and murder, to rule the city by the second exposition of 1929.", text_zh: "1887 年，少年奥诺弗雷·布维拉两手空空地从山村来到巴塞罗那，在即将举办的万国博览会工地上找到活计：给工人们散发无政府主义传单，再顺带推销生发水。从这里起步，他靠欺诈和谋杀，到 1929 年第二届博览会时已主宰了这座城市。", highlight_en: ["Universal Exposition"], highlight_zh: ["万国博览会"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_City_of_Marvels" },
  { id: "tdc-s1", kind: "scene", book_id: "temps-de-les-cireres", place_ids: ["es-barcelona"], location: "Throughout", location_zh: "全书", text_en: "In 1974, as Franco's regime executes the young anarchist Salvador Puig Antich, Natàlia Miralpeix comes home to Barcelona after twelve years in Paris and London. Visiting her father, her brother and the women of her family, she pieces together what the dictatorship has done to them and to the city.", text_zh: "1974 年，佛朗哥政权处决了年轻的无政府主义者萨尔瓦多·普伊赫·安蒂克。就在这时，娜塔莉娅·米拉尔佩伊斯在巴黎和伦敦待了十二年后回到巴塞罗那。她探望父亲、兄弟和家里的女人们，一点点拼出独裁对他们、对这座城市做了什么。", highlight_en: ["Natàlia Miralpeix"], highlight_zh: ["娜塔莉娅·米拉尔佩伊斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Montserrat_Roig" },
  { id: "mds-s1", kind: "scene", book_id: "mares-del-sur", place_ids: ["es-barcelona"], location: "Throughout", location_zh: "全书", text_en: "The body of Carlos Stuart Pedrell, a rich businessman who had told everyone he was off to the South Seas like Gauguin, is found stabbed on a building site in a poor suburb. His widow hires the gourmet detective Pepe Carvalho, who discovers that Stuart Pedrell never left Barcelona.", text_zh: "富商卡洛斯·斯图尔特·佩德雷尔曾对所有人说，他要像高更一样去南太平洋，可他的尸体却被发现死在一个贫民郊区的工地上，身中数刀。他的遗孀雇来美食家侦探佩佩·卡瓦略，卡瓦略发现斯图尔特·佩德雷尔根本没有离开巴塞罗那。", highlight_en: ["South Seas"], highlight_zh: ["南太平洋"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_South_Seas_(novel)" },
  { id: "oba-s1", kind: "scene", book_id: "obabakoak", place_ids: ["es-asteasu"], location: "Throughout", location_zh: "全书", text_en: "A web of stories about the people of Obaba, a Basque village: a schoolmaster's son who goes mad, a German teacher who never fits in, a boy who swallows a lizard that is said to eat his brain, and the writer who comes to a village inn to play a game of making stories out of other stories.", text_zh: "一组围绕巴斯克村庄奥巴巴的人们串联起来的故事：发了疯的教师之子，始终格格不入的德国女教师，一个据说吞进了蜥蜴、蜥蜴会吃掉他脑子的男孩，还有一位来到村里旅店、玩起“用别人的故事编故事”游戏的作家。", highlight_en: ["Obaba"], highlight_zh: ["奥巴巴"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Obabakoak" },
  { id: "jet-s1", kind: "scene", book_id: "juegos-edad-tardia", place_ids: ["es-madrid"], location: "Throughout", location_zh: "全书", text_en: "Gregorio Olías, a dull office clerk in Madrid who once dreamed of being a poet, invents for Gil, a provincial salesman who phones him at work, a brilliant other self: Augusto Faroni, poet, traveller and engineer. Gil believes every word, and when he comes to Madrid to meet Faroni, the game collapses.", text_zh: "格雷戈里奥·奥利亚斯是马德里一名乏味的办公室职员，年轻时梦想当诗人。他对一个常打电话到公司的外省推销员希尔，虚构了一个光彩照人的另一个自己：诗人、旅行家兼工程师奥古斯托·法罗尼。希尔对一切信以为真，等他来马德里要见法罗尼，这场游戏就崩塌了。", highlight_en: ["Augusto Faroni"], highlight_zh: ["奥古斯托·法罗尼"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Luis_Landero" },
  { id: "jpo-s1", kind: "scene", book_id: "jinete-polaco", place_ids: ["es-ubeda"], location: "Throughout", location_zh: "全书", text_en: "Manuel, a simultaneous interpreter, spends a winter in New York with Nadia, the daughter of an army officer from his home town. Between them, over nights of talk and a trunk of old photographs, they reconstruct a century of Mágina: its family secrets, a walled-up mummy, the war, and the town he fled as a young man.", text_zh: "同声传译员曼努埃尔和娜迪娅在纽约度过一个冬天，她是他家乡一位军官的女儿。两人在一夜夜的长谈和一箱老照片里，拼出马希纳的一百年：家族秘密、一具被砌进墙里的木乃伊、内战，还有他年轻时逃离的那座小城。", highlight_en: ["Mágina"], highlight_zh: ["马希纳"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Polish_Rider_(novel)" },
  { id: "cht-s1", kind: "scene", book_id: "corazon-tan-blanco", place_ids: ["es-madrid"], location: "Chapter 1", location_zh: "第一章", text_en: "'I did not want to know, but I have come to know': shortly after returning from her honeymoon, Teresa leaves the family lunch table in Madrid, goes into the bathroom, takes off her blouse in front of the mirror and shoots herself through the heart. Decades later her husband's son Juan, newly married himself, begins to learn why.", text_zh: "“我本不想知道，可还是知道了”：度完蜜月回来不久，特蕾莎在马德里家中从午饭桌边起身，走进浴室，对着镜子脱下上衣，朝自己心口开了一枪。几十年后，她丈夫的儿子胡安刚刚结婚，开始一点点知道其中的缘由。", highlight_en: ["shoots herself through the heart"], highlight_zh: ["朝自己心口开了一枪"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Heart_So_White" },
  { id: "meb-s1", kind: "scene", book_id: "manana-en-la-batalla", place_ids: ["es-madrid"], location: "Chapter 1", location_zh: "第一章", text_en: "Víctor, a screenwriter, is invited to dinner at the Madrid flat of Marta, a married woman whose husband is away in London. Before they can become lovers she falls ill and dies in his arms, her two-year-old son asleep in the next room. He leaves without telling anyone, and then cannot keep away from her family.", text_zh: "编剧维克托受邀到马尔塔在马德里的公寓吃晚饭，她已婚，丈夫在伦敦出差。两人还没成为情人，她就突然发病，死在他怀里，她两岁的儿子睡在隔壁房间。他悄悄离开，没告诉任何人，之后却怎么也放不下她的家人。", highlight_en: ["dies in his arms"], highlight_zh: ["死在他怀里"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Tomorrow_in_the_Battle_Think_on_Me" },
  { id: "sds-s1", kind: "scene", book_id: "soldados-de-salamina", place_ids: ["es-collell"], location: "Part 1", location_zh: "第一部", text_en: "As the Republicans retreat to France in January 1939, the Falangist writer Rafael Sánchez Mazas survives a mass shooting of prisoners at El Collell and hides in the woods. A young militiaman finds him, looks him in the eye, and calls back to the others that there is nobody there. Sixty years later a journalist named Javier Cercas sets out to find him.", text_zh: "1939 年 1 月，共和军向法国撤退，长枪党作家拉斐尔·桑切斯·马萨斯在科列尔的集体枪决中逃过一死，躲进树林。一个年轻民兵找到了他，直视着他的眼睛，却朝其他人喊：这里没人。六十年后，一个名叫哈维尔·塞尔卡斯的记者出发去寻找这名民兵。", highlight_en: ["there is nobody there"], highlight_zh: ["这里没人"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Soldiers_of_Salamis" },
  { id: "ain-s1", kind: "scene", book_id: "anatomia-de-un-instante", place_ids: ["es-congreso"], location: "Prologue", location_zh: "序章", text_en: "At 6.23 pm on 23 February 1981, Civil Guards burst into the chamber and open fire as the deputies vote. Everyone dives under the benches except three men: the outgoing prime minister Adolfo Suárez, the old general Gutiérrez Mellado, who stands up to face the gunmen, and the Communist leader Santiago Carrillo, who stays in his seat and lights a cigarette.", text_zh: "1981 年 2 月 23 日下午 6 点 23 分，国民警卫队冲进议事厅，在议员投票时开枪。所有人都钻到座位下，只有三个人例外：即将卸任的首相阿道弗·苏亚雷斯；老将军古铁雷斯·梅利亚多，他站起来直面枪手；还有共产党领袖圣地亚哥·卡里略，他坐在原位，点起一支烟。", highlight_en: ["except three men"], highlight_zh: ["只有三个人例外"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Anatomy_of_a_Moment" },
  { id: "sdv-s1", kind: "scene", book_id: "sombra-del-viento", place_ids: ["es-arc-teatre"], location: "Chapter 1", location_zh: "第一章", text_en: "One dawn in 1945 a bookseller takes his ten-year-old son Daniel, who can no longer remember his dead mother's face, to the Cemetery of Forgotten Books, a labyrinth of shelves in an old building in the Raval. Each first visitor must adopt one book; Daniel chooses The Shadow of the Wind by Julián Carax, and someone, he soon finds, is burning every other copy.", text_zh: "1945 年的一个清晨，书商带着十岁的儿子达尼埃尔——他已记不起死去母亲的面容——来到“遗忘书之墓”，那是拉瓦尔区一座老楼里迷宫般的书架。第一次来的人都要领养一本书；达尼埃尔选中了胡利安·卡拉克斯的《风之影》，不久他发现，有人正在烧掉这本书的其他所有存本。", highlight_en: ["Cemetery of Forgotten Books"], highlight_zh: ["遗忘书之墓"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Shadow_of_the_Wind" },
  { id: "gci-s1", kind: "scene", book_id: "girasoles-ciegos", place_ids: ["es-madrid"], location: "Fourth story", location_zh: "第四个故事", text_en: "In postwar Madrid, Ricardo, a Republican, hides in a wardrobe in the family flat while his wife Elena pretends to be a widow. Brother Salvador, a young deacon who teaches their son at school, becomes obsessed with Elena, and when he forces his way into the flat, Ricardo is discovered.", text_zh: "战后的马德里，共和派里卡多藏在自家公寓的衣柜里，妻子埃莱娜装作寡妇。在学校教他们儿子的年轻执事萨尔瓦多修士迷恋上了埃莱娜，当他强行闯进公寓时，里卡多暴露了。", highlight_en: ["hides in a wardrobe"], highlight_zh: ["藏在自家公寓的衣柜里"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Blind_Sunflowers_(novel)" },
  { id: "chl-s1", kind: "scene", book_id: "corazon-helado", place_ids: ["es-madrid"], location: "Opening", location_zh: "开篇", text_en: "At the Madrid funeral of Julio Carrión, a rich businessman who rose from nothing after the war, his son Álvaro notices a beautiful stranger who leaves early. Tracing her, he finds that her family, Republican exiles, were ruined in the 1940s, and that their losses and his father's fortune are the same story.", text_zh: "在马德里白手起家的富商胡利奥·卡里翁的葬礼上，他的儿子阿尔瓦罗注意到一个提前离开的美丽陌生女人。追查下去，他发现她的家人是共和派流亡者，在 20 世纪 40 年代家破人亡，而他们的失去和父亲的发家原来是同一个故事。", highlight_en: ["funeral of Julio Carrión"], highlight_zh: ["胡利奥·卡里翁的葬礼"], status: "draft", fact_source: "https://es.wikipedia.org/wiki/El_coraz%C3%B3n_helado" },
  { id: "pat-s1", kind: "scene", book_id: "patria-aramburu", place_ids: ["es-donostia"], location: "Opening", location_zh: "开篇", text_en: "On the day ETA announces it is giving up violence in 2011, Bittori goes to the cemetery to tell her husband, the Txato, shot dead years before outside his transport business. She decides to move back from San Sebastián to her village, to the house next to that of Miren, once her closest friend, whose son Joxe Mari is in prison for the killing.", text_zh: "2011 年“埃塔”宣布放弃暴力那天，比托丽去墓地告诉丈夫“小胖子”——他多年前在自家运输公司门外被枪杀。她决定从圣塞巴斯蒂安搬回村里，住回米伦家隔壁。米伦曾是她最好的朋友，儿子何塞·马里正因这桩命案坐牢。", highlight_en: ["Bittori"], highlight_zh: ["比托丽"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Patria_(novel)" },
  { id: "lef-s1", kind: "scene", book_id: "lectura-facil", place_ids: ["es-barcelona"], location: "Throughout", location_zh: "全书", text_en: "Four women cousins with intellectual disabilities share a supervised flat in Barcelona: Nati, who refuses to obey, Patri, Àngels, who is writing a novel on WhatsApp, and Marga, whom a court wants to have sterilised. Through squats, anarchist assemblies and dance classes they fight the institutions that claim to protect them.", text_zh: "四个有智力障碍的表姐妹住在巴塞罗那一套有人看管的公寓里：拒绝服从的纳蒂、帕特里、在手机聊天软件上写小说的安赫尔斯，还有法院要给她做绝育手术的玛加。在占屋、无政府主义集会和舞蹈课之间，她们对抗着那些声称在保护她们的机构。", highlight_en: ["sterilised"], highlight_zh: ["绝育手术"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lectura_f%C3%A1cil" },
  { id: "mco-s1", kind: "scene", book_id: "mala-costumbre", place_ids: ["es-san-blas"], location: "Throughout", location_zh: "全书", text_en: "Growing up in a working-class family in San Blas in the 1980s, a girl the world takes for a boy finds refuge in films, myths and books, and learns early to hide. As heroin sweeps through the neighbourhood and its trans women are mocked and beaten, she begins, step by step, to become herself.", text_zh: "20 世纪 80 年代在圣布拉斯一个工人家庭长大的女孩，被所有人当作男孩。她在电影、神话和书里找到庇护，很早就学会了隐藏。海洛因席卷街区，这里的跨性别女性受尽嘲笑和殴打，她却一步步开始成为自己。", highlight_en: ["San Blas"], highlight_zh: ["圣布拉斯"], status: "draft", fact_source: "https://www.anagrama-ed.es/libro/narrativas-hispanicas/la-mala-costumbre/9788433929608/NH_741" },
  { id: "fwt-s1", kind: "scene", book_id: "for-whom-the-bell-tolls", place_ids: ["es-navacerrada"], location: "Chapters 1, 43", location_zh: "第一章、第四十三章", text_en: "Robert Jordan, an American who has volunteered for the Republic, comes into the Guadarrama to blow up a bridge at the start of an offensive. Over three days with Pablo's guerrilla band he falls in love with María and hears Pilar's stories of the war; the bridge is blown, but he is wounded, and stays behind alone with a machine gun to hold off the enemy.", text_zh: "为共和国而来的美国志愿者罗伯特·乔丹来到瓜达拉马山，要在攻势开始时炸掉一座桥。和巴勃罗的游击队相处的三天里，他爱上了玛丽亚，听皮拉尔讲内战的往事。桥炸掉了，他却受了伤，独自留下，用一挺机枪阻挡敌人。", highlight_en: ["blow up a bridge"], highlight_zh: ["炸掉一座桥"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/For_Whom_the_Bell_Tolls" },
  { id: "sar-es-s1", kind: "scene", book_id: "fr-sun-also-rises", place_ids: ["es-cafe-iruna"], location: "Book II, chapters 15–18", location_zh: "第二部第十五至十八章", text_en: "For the fiesta of San Fermín, Jake Barnes, Lady Brett Ashley and their friends come to Pamplona from Paris. Between the running of the bulls and the afternoon fights they drink in the cafés on the square, and Brett runs off with the nineteen-year-old matador Pedro Romero.", text_zh: "为了圣费尔明节，杰克·巴恩斯、布蕾特·阿什利夫人和朋友们从巴黎来到潘普洛纳。在清晨的奔牛和午后的斗牛之间，他们泡在广场边的咖啡馆里喝酒；布蕾特和十九岁的斗牛士佩德罗·罗梅罗私奔了。", highlight_en: ["San Fermín"], highlight_zh: ["圣费尔明节"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Sun_Also_Rises" },
  { id: "fos-s1", kind: "scene", book_id: "fountains-of-silence", place_ids: ["es-castellana-hilton"], location: "Throughout", location_zh: "全书", text_en: "In the summer of 1957 Daniel Matheson, son of a Texas oil tycoon and a Spanish mother, arrives with his parents at the Castellana Hilton with a camera. He falls for Ana, a maid at the hotel whose family are the children of executed Republicans, and his photographs begin to show the silence that Franco's Spain is built on, including its stolen babies.", text_zh: "1957 年夏天，得州石油大亨和西班牙母亲的儿子丹尼尔·马西森带着相机，随父母住进卡斯特利亚纳希尔顿酒店。他爱上了酒店女仆安娜，她家是被处决的共和派留下的孩子；他的照片渐渐拍出了佛朗哥西班牙赖以建立的沉默，包括被偷走的婴儿。", highlight_en: ["Castellana Hilton"], highlight_zh: ["卡斯特利亚纳希尔顿酒店"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Ruta_Sepetys" },
  // —— 11-22 quotations from Spanish Wikisource (and Homage to Catalonia from Project Gutenberg Australia), replacing the placeholder scene notes (add_es3.py) ——
  { id: "cid-1", book_id: "cantar-de-mio-cid", place_ids: ["es-burgos-cathedral"], location: "Cantar I, lines 15–20", location_zh: "第一歌，第 15–20 行", text_orig: "Mio Cid Ruy Diaz por Burgos entraba,\nEn su compaña LX. pendones lebaba\nExienlo ver mugieres e várones,\nBurgeses e Burgesas por las finiestras son puestas,\nPlorando de los oios, tanto avien el dolor,\nDe las sus bocas todos dician una razon:\nDios que buen Vasalo si oviese buen Señor!", highlight_orig: ["Burgos"], text_en: "My Cid Ruy Díaz rode into Burgos,\nsixty pennons in his company;\nmen and women came out to see him,\nthe burghers and their wives stood at the windows,\nweeping from their eyes, so great was their grief.\nFrom every mouth came one saying:\n'God, what a good vassal, if only he had a good lord!'", highlight_en: ["Burgos"], text_zh: "我的熙德鲁伊·迪亚斯进入布尔戈斯，\n随行六十面旌旗；\n男男女女出来看他，\n市民和他们的妻子都站在窗前，\n泪流满面，悲痛至极。\n人人口中说着同一句话：\n“天哪，多好的臣子，可惜没有一位好主君！”", highlight_zh: ["布尔戈斯"], translation: "own", status: "draft", checked: "Spanish Wikisource, Colección de poesías castellanas anteriores al siglo XV/Tomo I/Poema del Cid (Sánchez's line numbers and bracket left out), 2026-11-22" },
  { id: "cid-2", book_id: "cantar-de-mio-cid", place_ids: ["es-burgos-cathedral"], location: "Cantar I, lines 50–56", location_zh: "第一歌，第 50–56 行", text_orig: "Ya lo vee el Cid que del Rey non avie gracia:\nPartiós' de la puerta por Burgos aguijaba:\nLegó à Sancta Maria, luego descavalgaba:\nFincó los ynoios, de corazon rogaba.\nLa oracion fecha luego cavalgaba:\nSalió por la puerta, è en Arlanzon posaba,\nCabo esa Villa en la Glera posaba.", highlight_orig: ["Sancta Maria"], text_en: "The Cid sees now that he has no favour from the king.\nHe leaves the door and spurs on through Burgos;\nhe comes to Santa María, and at once dismounts,\nfalls on his knees, and prays from his heart.\nThe prayer made, he mounts again,\nrides out through the gate and camps by the Arlanzón,\nbeside that town, upon the sandbank.", highlight_en: ["Santa María"], text_zh: "熙德这才明白，国王不肯开恩。\n他离开那扇门，策马穿过布尔戈斯；\n来到圣玛利亚教堂，随即下马，\n双膝跪地，诚心祈祷。\n祷告完毕，他又上马，\n出了城门，在阿兰松河边扎营，\n就在城外的沙洲上。", highlight_zh: ["圣玛利亚教堂"], translation: "own", status: "draft", checked: "Spanish Wikisource, Colección de poesías castellanas anteriores al siglo XV/Tomo I/Poema del Cid (Sánchez's line numbers and bracket left out), 2026-11-22" },
  { id: "lba-1", book_id: "libro-de-buen-amor", place_ids: ["es-hita"], location: "Stanza 575", location_zh: "第 575 节", text_orig: "Yo Joan Ruis, el sobredicho arçipreste de Hita,\nporque mi coraçón de trovar non se quita,\nnunca fallé tal dueña como a vos Amor pinta,\nnin creo que la falle en toda esta coyta.", highlight_orig: ["arçipreste de Hita"], text_en: "I, Juan Ruiz, the aforesaid Archpriest of Hita,\nthough my heart never gives up making verses,\nnever found such a lady as Love paints for you,\nnor do I think I shall find her in all this trouble.", highlight_en: ["Archpriest of Hita"], text_zh: "我，胡安·鲁伊斯，前面说过的伊塔大司铎，\n虽然我的心从不停止作诗，\n却从没遇见过爱神为你描绘的那样一位女子，\n我想在这一切苦恼里也不会遇见。", highlight_zh: ["伊塔大司铎"], translation: "own", status: "draft", checked: "Spanish Wikisource, Libro de Buen Amor/041C, 2026-11-22" },
  { id: "luc-1", book_id: "conde-lucanor", place_ids: ["es-penafiel"], location: "The author's preface", location_zh: "作者前言", text_orig: "Et los libros que él fizo son éstos, que él a fecho fasta aquí: la Crónica abreviada, el Libro de los sabios, el Libro de la cavallería, el Libro del infante, el Libro del cavallero et del escudero, el Libro del Conde, el Libro de la caça, el Libro de los engeños, el Libro de los cantares. Et estos libros están en el monesterio de los fraires predicadores que él fizo en Peñafiel.", highlight_orig: ["Peñafiel"], text_en: "And the books he has made so far are these: the Abridged Chronicle, the Book of the Wise, the Book of Chivalry, the Book of the Prince, the Book of the Knight and the Squire, the Book of the Count, the Book of Hunting, the Book of Engines, the Book of Songs. And these books are in the monastery of the Preaching Friars that he founded at Peñafiel.", highlight_en: ["Peñafiel"], text_zh: "他至今写成的书有这些：《编年史略》《智者之书》《骑士之书》《王子之书》《骑士与侍从之书》《伯爵之书》《狩猎之书》《器械之书》《歌谣之书》。这些书都存放在他在佩尼亚菲尔创建的多明我会修道院里。", highlight_zh: ["佩尼亚菲尔"], translation: "own", status: "draft", checked: "Spanish Wikisource, Conde Lucanor/Anteprólogo, 2026-11-22" },
  { id: "cel-1", book_id: "la-celestina", place_ids: ["es-huerto-calixto"], location: "Act XIX", location_zh: "第十九幕", text_orig: "SOSIA.- ¡O Tristán, discreto mancebo! Mucho más me has dicho, que tu edad demanda. Astuta sospecha has remontado e creo que verdadera. Pero, porque ya llegamos al huerto e nuestro amo se nos acerca, dexemos este cuento, que es muy largo, para otro día.\nCALISTO.- Poned, moços, la escala e callad, que me paresce que está hablando mi señora de dentro. Sobiré encima de la pared y en ella estaré escuchando, por ver si oyré alguna buena señal de mi amor en absencia.", highlight_orig: ["huerto", "pared"], text_en: "SOSIA. O Tristán, wise lad! You have told me much more than your years call for. A shrewd suspicion you have flushed, and I believe a true one. But since we have reached the garden and our master is coming up to us, let us leave this story, which is very long, for another day.\nCALISTO. Set up the ladder, lads, and be quiet, for I think my lady is talking inside. I will climb on top of the wall and listen from there, to see whether I hear some good sign of my love while I am away.", highlight_en: ["the garden", "the wall"], text_zh: "索西亚：啊，特里斯坦，你真是个聪明小伙子！你跟我说的远远超出了你这个年纪。你嗅出了一个精明的怀疑，我相信是真的。不过我们已经到了花园，主人也朝我们走过来了，这个故事太长，留到改天再说吧。\n卡利斯托：孩子们，把梯子架好，别出声，我好像听见我的小姐在里面说话。我爬到墙头上去，在那儿听着，看能不能听到她在我不在时说起我的什么好话。", highlight_zh: ["花园", "墙头"], translation: "own", status: "draft", checked: "Spanish Wikisource, La Celestina (1913)/Aucto décimonono; spacing after the speaker's name evened, 2026-11-22" },
  { id: "cel-2", book_id: "la-celestina", place_ids: ["es-huerto-calixto"], location: "Act XIX", location_zh: "第十九幕", text_orig: "TRISTÁN.- Tente, señor, no baxes, que ydos son; que no era sino Traso el coxo e otros vellacos, que passauan bozeando. Que ya se torna Sosia. Tente, tente, señor, con las manos al escala.\nCALISTO.- ¡O!, ¡válame Santa María! ¡Muerto soy! ¡Confessión!\nTRISTÁN.- Llégate presto, Sosia, que el triste de nuestro amo es caydo del escala e no habla ni se bulle.", highlight_orig: ["caydo del escala"], text_en: "TRISTÁN. Hold on, sir, don't come down, they've gone; it was only Traso the Lame and some other rogues going by shouting. Sosia is coming back now. Hold on, hold on, sir, with your hands on the ladder.\nCALISTO. Oh, Holy Mary save me! I am dead! Confession!\nTRISTÁN. Come quick, Sosia, our poor master has fallen from the ladder and neither speaks nor moves.", highlight_en: ["fallen from the ladder"], text_zh: "特里斯坦：等等，老爷，别下来，他们走了；不过是瘸子特拉索和别的几个无赖，一路喊着过去了。索西亚已经回来了。抓住，抓住梯子，老爷！\n卡利斯托：啊，圣母玛利亚救我！我要死了！我要忏悔！\n特里斯坦：快过来，索西亚，我们可怜的主人从梯子上摔下来了，不说话也不动了。", highlight_zh: ["从梯子上摔下来了"], translation: "own", status: "draft", checked: "Spanish Wikisource, La Celestina (1913)/Aucto décimonono; spacing after the speaker's name evened, 2026-11-22" },
  { id: "laz-1", book_id: "lazarillo-de-tormes", place_ids: ["es-verraco-salamanca"], location: "Tratado I", location_zh: "第一章", text_orig: "Salimos de Salamanca, y llegando a la puente, está a la entrada de ella un animal de piedra, que casi tiene forma de toro, y el ciego mandóme que llegase cerca del animal y, allí puesto, me dijo:\n—Lázaro: llega el oído a este toro y oirás gran ruido dentro de él.\nYo simplemente llegué, creyendo ser así. Y como sintió que tenía la cabeza par de la piedra, afirmó recio la mano y dióme una gran calabazada en el diablo del toro, que más de tres días me duró el dolor de la cornada, y díjome:\n—Necio, aprende, que el mozo del ciego un punto ha de saber más que el diablo.\nY rió mucho la burla.", highlight_orig: ["Salamanca", "un animal de piedra, que casi tiene forma de toro"], text_en: "We left Salamanca, and coming to the bridge, there is at its entrance an animal of stone that has almost the shape of a bull, and the blind man told me to go up close to the animal, and when I was there he said:\n'Lázaro, put your ear to this bull and you will hear a great noise inside it.'\nI, simple as I was, went up, believing it to be so. And as soon as he felt my head close to the stone, he struck out hard with his hand and banged my head against that devil of a bull, so that the pain of the goring lasted me more than three days, and he said to me:\n'Fool, learn that a blind man's boy must know one point more than the devil.'\nAnd he laughed a great deal at the joke.", highlight_en: ["Salamanca", "an animal of stone that has almost the shape of a bull"], text_zh: "我们出了萨拉曼卡，来到桥头，桥口有一头石头雕的牲口，样子差不多像一头牛。瞎子叫我走到那牲口跟前，我站好了，他就说：\n“拉撒路，把耳朵贴到这头牛上，你会听见里面有很大的声响。”\n我老老实实地凑上去，以为真是这样。他一觉出我的头挨着石头，就使劲一推，让我的脑袋在那头见鬼的牛上狠狠撞了一下，这一“牛角顶”疼了我三天还多。他对我说：\n“傻瓜，记住，给瞎子领路的孩子得比魔鬼还多懂一分。”\n他为这个恶作剧笑了好半天。", highlight_zh: ["萨拉曼卡", "石头雕的牲口，样子差不多像一头牛"], translation: "own", status: "draft", checked: "Spanish Wikisource, El Lazarillo de Tormes/Tratado primero, 2026-11-22" },
  { id: "vida-1", book_id: "libro-de-la-vida", place_ids: ["es-encarnacion-avila"], location: "Chapter 9", location_zh: "第九章", text_orig: "Pues ya andaba mi alma cansada, y, aunque queria, no la dejaban descansar las ruines costumbres que tenia. Acaecióme, que entrando un dia en el oratorio, vi una imágen que habian traido allí á guardar, que se habia buscado para cierta fiesta que se hacia en casa. Era de Cristo muy llagado, y tan devota, que en mirándola, toda me turbó de verle tal, porque representaba bien lo que pasó por nosotros. Fué tanto lo que sentí de lo mal que habia agradecido aquellas llagas, que el corazon me parece se me partia; y arrojéme cabe él con grandísimo derramamiento de lágrimas, suplicándole me fortaleciese ya de una vez, para no ofenderle.", highlight_orig: ["el oratorio", "en casa"], text_en: "My soul was now weary, and, though it wished to, the bad habits I had would not let it rest. It happened that, going one day into the oratory, I saw an image that had been brought there to be kept, which had been got for a certain feast held in the house. It was of Christ sorely wounded, and so devout that, as I looked at it, I was utterly shaken to see him so, for it showed well what he went through for us. So great was what I felt at how badly I had thanked him for those wounds that my heart seemed to break; and I threw myself down beside him with a great flood of tears, begging him to strengthen me once and for all, so that I would not offend him.", highlight_en: ["the oratory", "the house"], text_zh: "那时我的灵魂已经疲惫不堪，虽然它想安歇，我那些恶习却不让它安歇。有一天我走进祈祷室，看见一尊像，是为院里要办的某个节日找来、暂时放在那里的。那是一尊遍体伤痕的基督像，那样虔敬动人，我一看见他这副模样，整个人都震动了，因为它真切地表现出他为我们受的苦。想到自己对这些伤痕是多么不知感恩，我的心仿佛要碎了；我扑倒在他身旁，泪如泉涌，求他一劳永逸地坚固我，使我不再冒犯他。", highlight_zh: ["祈祷室", "院里"], translation: "own", status: "draft", checked: "Spanish Wikisource, Su vida (Santa Teresa de Jesús)/Capítulo IX, 2026-11-22" },
  { id: "dq-1", book_id: "don-quixote", place_ids: ["es-criptana"], location: "Part I, chapter 8", location_zh: "上卷第八章", text_orig: "En esto descubrieron treinta ó cuarenta molinos de viento que hay en aquel campo; y así como don Quijote los vió, dijo á su escudero:\n—La ventura va guiando nuestras cosas mejor de lo que acertáramos á desear; porque ves allí, amigo Sancho Panza, donde se descubren treinta ó pocos más desaforados gigantes, con quien pienso hacer batalla y quitarles á todos las vidas, con cuyos despojos comenzaremos á enriquecer; que esta es buena guerra, y es gran servicio de Dios quitar tan mala simiente de sobre la faz de la tierra.\n—¿Qué gigantes? dijo Sancho Panza.\n—Aquellos que allí ves, respondió su amo, de los brazos largos, que los suelen tener algunos de casi dos leguas.\n—Mire vuestra merced, respondió Sancho, que aquellos que allí se parecen no son gigantes, sino molinos de viento, y lo que en ellos parecen brazos son las aspas, que, volteadas del viento, hacen andar la piedra del molino.", highlight_orig: ["treinta ó cuarenta molinos de viento"], text_en: "Just then they came in sight of thirty or forty windmills that there are on that plain, and as soon as Don Quixote saw them he said to his squire:\n'Fortune is guiding our affairs better than we could have wished; for look there, friend Sancho Panza, where thirty or more monstrous giants appear, with whom I mean to do battle and take all their lives, and with their spoils we shall begin to grow rich; for this is fair war, and it is a great service to God to sweep so evil a breed from the face of the earth.'\n'What giants?' said Sancho Panza.\n'Those you see there,' answered his master, 'with the long arms, for some of them are wont to have them almost two leagues long.'\n'Look, your worship,' answered Sancho, 'those that appear there are not giants but windmills, and what seem to be arms in them are the sails, which, turned by the wind, make the millstone go.'", highlight_en: ["thirty or forty windmills"], text_zh: "这时，他们看见野地里有三四十架风车。堂吉诃德一看见，就对侍从说：\n“命运把我们的事安排得比我们希望的还好。你瞧，桑丘·潘沙朋友，那边出现了三十多个奇大无比的巨人，我要同他们交战，把他们统统杀死，用他们的战利品开始发家致富。这是正义的战争，把这些坏种从地面上扫除干净，也是为上帝立了大功。”\n“什么巨人？”桑丘·潘沙说。\n“就是你看见的那些，”他的主人回答，“胳膊长长的，有的胳膊差不多有两里瓦长。”\n“您瞧，”桑丘回答，“那边的不是巨人，是风车；那些像胳膊的东西是风车的翼子，被风一吹转起来，就带动磨石。”", highlight_zh: ["三四十架风车"], translation: "own", status: "draft", checked: "Spanish Wikisource, El ingenioso hidalgo Don Quijote de la Mancha (1905)/Tomo I/Capítulo VIII (the chapter's first letter, printed as a picture, restored), 2026-11-22" },
  { id: "nov-1", book_id: "novelas-ejemplares", place_ids: ["es-cervantes-valladolid"], location: "The Dialogue of the Dogs, opening", location_zh: "《双狗对话》开篇", text_orig: "Novela y coloquio que pasó entre Cipión y Berganza, perros del Hospital de la Resurrección, que está en la Ciudad de Valladolid, fuera de la puerta del campo, a quien comúnmente llaman «Los perros de Mahude».\nCIPIÓN.—Berganza amigo, dejemos esta noche el Hospital en guarda de la confianza y retirémonos a esta soledad y entre estas esteras, donde podremos gozar sin ser sentidos desta no vista merced que el cielo en un mismo punto a los dos nos ha hecho.\nBERGANZA.—Cipión hermano, óyote hablar y sé que te hablo, y no puedo creerlo, por parecerme que el hablar nosotros pasa de los términos de naturaleza.", highlight_orig: ["Hospital de la Resurrección", "Valladolid"], text_en: "Novel and dialogue that passed between Cipión and Berganza, dogs of the Hospital of the Resurrection, which is in the City of Valladolid, outside the Puerta del Campo, and who are commonly called 'the dogs of Mahude'.\nCIPIÓN. Berganza, my friend, let us leave the Hospital tonight in the keeping of trust and withdraw to this quiet place, among these mats, where we can enjoy unnoticed this unheard-of favour that heaven has done the two of us at one and the same moment.\nBERGANZA. Brother Cipión, I hear you speak and I know that I am speaking to you, and I cannot believe it, for it seems to me that our speaking goes beyond the bounds of nature.", highlight_en: ["Hospital of the Resurrection", "Valladolid"], text_zh: "西皮翁与贝尔甘萨之间的小说兼对话。这两条狗属于巴利亚多利德城坎波门外的复活医院，人们通常管它们叫“马乌德的狗”。\n西皮翁：贝尔甘萨朋友，今晚我们就把医院交给信任去看守，躲到这僻静地方、这些草席中间来吧，在这里我们可以不被人察觉，享受上天同时赐给我们俩的这份闻所未闻的恩典。\n贝尔甘萨：西皮翁兄弟，我听见你说话，也知道我在跟你说话，可我不敢相信，因为我觉得我们会说话，已经超出了自然的界限。", highlight_zh: ["复活医院", "巴利亚多利德"], translation: "own", status: "draft", checked: "Spanish Wikisource, El coloquio de los perros (1825), 2026-11-22" },
  { id: "fov-1", book_id: "fuenteovejuna", place_ids: ["es-fuente-obejuna"], location: "Act III", location_zh: "第三幕", text_orig: "ESTEBAN: Déjenme un poco.\nJUEZ: Ya os dejo.\nDecid: ¿quién mató a Fernando?\nESTEBAN: Fuenteovejuna lo hizo.\n…\nJUEZ: Que os he de matar, creed,\nen este potro, villanos.\n¿Quién mató al comendador?\nPASCUALA: Fuenteovejuna, señor.", highlight_orig: ["Fuenteovejuna"], text_en: "ESTEBAN: Let me be a moment.\nJUDGE: I will.\nNow tell me: who killed Fernando?\nESTEBAN: Fuenteovejuna did it.\n…\nJUDGE: I'll kill you, believe me,\non this rack, you peasants.\nWho killed the Commander?\nPASCUALA: Fuenteovejuna, sir.", highlight_en: ["Fuenteovejuna"], text_zh: "埃斯特万：让我歇一会儿。\n法官：好，让你歇。\n说吧：谁杀了费尔南多？\n埃斯特万：是羊泉村干的。\n…\n法官：相信我，我要让你们这些乡巴佬\n死在这刑架上。\n谁杀了骑士团长？\n帕斯夸拉：羊泉村，大人。", highlight_zh: ["羊泉村"], translation: "own", status: "draft", checked: "Spanish Wikisource, Fuenteovejuna/Acto III; spacing after the speaker's name evened, 2026-11-22" },
  { id: "olm-1", book_id: "caballero-de-olmedo", place_ids: ["es-olmedo"], location: "Act III", location_zh: "第三幕", text_orig: "Que de noche le mataron\nal caballero,\nla gala de Medina,\nla flor de Olmedo.", highlight_orig: ["la flor de Olmedo"], text_en: "For by night they killed him,\nthe knight,\nthe pride of Medina,\nthe flower of Olmedo.", highlight_en: ["the flower of Olmedo"], text_zh: "夜里他们杀了他，\n那位骑士，\n梅迪纳的骄傲，\n奥尔梅多之花。", highlight_zh: ["奥尔梅多之花"], translation: "own", status: "draft", checked: "Spanish Wikisource, El caballero de Olmedo/Acto III, 2026-11-22" },
  { id: "bur-1", book_id: "burlador-de-sevilla", place_ids: ["es-sevilla"], location: "Act II", location_zh: "第二幕", text_orig: "Sevilla a voces me llama\nel burlador, y el mayor\ngusto que en mí puede haber\nes burlar una mujer\ny dejarla sin honor.", highlight_orig: ["Sevilla"], text_en: "Seville cries me out by name\nthe Trickster, and the greatest\npleasure there can be for me\nis to trick a woman\nand leave her without honour.", highlight_en: ["Seville"], text_zh: "整个塞维利亚都大声叫我\n“骗子”，而我最大的\n乐趣，就是\n骗一个女人，\n让她名誉扫地。", highlight_zh: ["塞维利亚"], translation: "own", status: "draft", checked: "Spanish Wikisource, El burlador de Sevilla/Acto II (the edition's verse indent left out), 2026-11-22" },
  { id: "bus-1", book_id: "el-buscon", place_ids: ["es-segovia"], location: "Book I, chapter 1", location_zh: "第一卷第一章", text_orig: "Yo, señora, soy de Segovia. Mi padre se llamó Clemente Pablo, natural del mismo pueblo; Dios le tenga en el cielo. Fue, tal como todos dicen, de oficio barbero, aunque eran tan altos sus pensamientos que se corría de que le llamasen así, diciendo que él era tundidor de mejillas y sastre de barbas.", highlight_orig: ["Segovia"], text_en: "I, madam, am from Segovia. My father was called Clemente Pablo, a native of the same town; God keep him in heaven. He was, as everyone says, a barber by trade, though his thoughts ran so high that he was ashamed to be called that, saying he was a shearer of cheeks and a tailor of beards.", highlight_en: ["Segovia"], text_zh: "夫人，我是塞哥维亚人。我父亲叫克莱门特·巴勃罗，也是本地人，愿上帝让他在天堂安息。正如大家所说，他的营生是剃头匠，不过他心气极高，被人这么叫就觉得丢脸，说自己是“脸颊的剪毛匠、胡子的裁缝”。", highlight_zh: ["塞哥维亚"], translation: "own", status: "draft", checked: "Spanish Wikisource, Historia de la vida del Buscón/Libro Primero: Capítulo I, 2026-11-22" },
  { id: "zal-1", book_id: "alcalde-de-zalamea", place_ids: ["es-zalamea"], location: "Act III", location_zh: "第三幕", text_orig: "CRESPO: Mirad que echado en el suelo\nmi honor a voces os pido.\nÁLVARO: ¡Qué enfado!\nCRESPO: Mirad que soy\nalcalde en Zalamea hoy.\nÁLVARO: Sobre mí no habéis tenido\njurisdicción. Es consejo\nde guerra enviará por mí.", highlight_orig: ["Zalamea"], text_en: "CRESPO: See, flung on the ground,\nI beg you aloud for my honour.\nÁLVARO: What a nuisance!\nCRESPO: See, I am\nmayor in Zalamea today.\nÁLVARO: Over me you have never had\njurisdiction. The council\nof war will send for me.", highlight_en: ["Zalamea"], text_zh: "克雷斯波：您看，我跪倒在地，\n高声求您还我名誉。\n阿尔瓦罗：真烦人！\n克雷斯波：您看，我今天\n是萨拉梅亚的镇长。\n阿尔瓦罗：你对我从来没有\n管辖权。军事法庭\n会派人来提我的。", highlight_zh: ["萨拉梅亚"], translation: "own", status: "draft", checked: "Spanish Wikisource, El alcalde de Zalamea/Jornada Tercera ('Es consejo' as printed, for 'El consejo'), 2026-11-22" },
  { id: "sdn-1", book_id: "si-de-las-ninas", place_ids: ["es-alcala"], location: "Act I, scene 1 (the inn at Alcalá)", location_zh: "第一幕第一场（阿尔卡拉的客栈）", text_orig: "SIMÓN. Ello también ha sido extraña determinación la de estarse usted dos días enteros sin salir de la posada. Cansa el leer, cansa el dormir... Y sobre todo, cansa la mugre del cuarto, las sillas desvencijadas, las estampas del hijo pródigo, el ruido de campanillas y cascabeles y la conversación ronca de carromateros y patanes, que no permiten un instante de quietud.", highlight_orig: ["la posada"], text_en: "SIMÓN. It was a strange decision, too, for you to stay two whole days without leaving the inn. One gets tired of reading, tired of sleeping... And above all, tired of the grime of the room, the rickety chairs, the prints of the Prodigal Son, the noise of handbells and harness bells, and the hoarse talk of carters and yokels, which never allows a moment's peace.", highlight_en: ["the inn"], text_zh: "西蒙：您这一回也真是古怪，整整两天待在客栈里不出门。读书读累了，睡觉睡累了……最累人的是房间里的油垢、东倒西歪的椅子、画着浪子回头的版画，还有铃铛和马铃的叮当声，车夫和乡巴佬粗哑的说话声，叫人片刻不得安宁。", highlight_zh: ["客栈"], translation: "own", status: "draft", checked: "Spanish Wikisource, El sí de las niñas (1830)/Acto primero; the page's line ends inside the speech joined, 2026-11-22" },
  { id: "alv-1", book_id: "don-alvaro", place_ids: ["es-hornachuelos"], location: "Act V, last scene", location_zh: "第五幕末场", text_orig: "DON ÁLVARO\n(Desde un risco, con sonrisa diabólica, todo convulso, dice:)\nBusca, imbécil, al P. Rafael...\nYo soy un enviado del infierno,\nsoy el demonio exterminador...\nHuid, miserables.\nTODOS\n¡Jesús, Jesús!\nDON ÁLVARO\nInfierno, abre tu boca y trágame.\nHúndase el cielo, perezca la raza humana;\nexterminio, destrucción...\n(Sube a lo más alto del monte y se precipita.)", highlight_orig: ["Desde un risco", "lo más alto del monte"], text_en: "DON ÁLVARO\n(From a crag, with a diabolical smile, convulsed all over, he says:)\nLook for Father Rafael, you fool...\nI am an envoy from hell,\nI am the destroying demon...\nFlee, you wretches.\nALL\nJesus, Jesus!\nDON ÁLVARO\nHell, open your mouth and swallow me.\nLet heaven fall, let the human race perish;\nextermination, destruction...\n(He climbs to the highest point of the mountain and throws himself off.)", highlight_en: ["From a crag", "the highest point of the mountain"], text_zh: "唐阿尔瓦罗\n（站在一块岩石上，脸上带着魔鬼般的笑，浑身抽搐，说：）\n去找拉斐尔神父吧，蠢货……\n我是地狱派来的使者，\n我是灭绝一切的魔鬼……\n逃命吧，可怜虫们。\n众人\n耶稣啊，耶稣！\n唐阿尔瓦罗\n地狱啊，张开你的嘴，把我吞下去。\n让天塌下来，让人类灭亡；\n毁灭，摧毁……\n（他爬上山的最高处，纵身跳下。）", highlight_zh: ["站在一块岩石上", "山的最高处"], translation: "own", status: "draft", checked: "Spanish Wikisource, Don Álvaro o La fuerza del sino/Jornada quinta, 2026-11-22" },
  { id: "ten-1", book_id: "don-juan-tenorio", place_ids: ["es-hosteria-laurel"], location: "Part I, Act I, scene 8", location_zh: "第一部第一幕第八场", text_orig: "DIEGO.\n¿La hostería del Laurel?\nBUTT.\nEn ella estáis, caballero.\nDIEGO.\n¿Está en casa el hostelero?\nBUTT.\nEstáis hablando con él.\nDIEGO.\n¿Sois vos Buttarelli?\nBUTT.\nYo.", highlight_orig: ["La hostería del Laurel"], text_en: "DIEGO.\nThe Laurel inn?\nBUTT.\nYou are in it, sir.\nDIEGO.\nIs the innkeeper at home?\nBUTT.\nYou are speaking to him.\nDIEGO.\nAre you Buttarelli?\nBUTT.\nI am.", highlight_en: ["The Laurel inn"], text_zh: "迭戈\n是月桂客栈吗？\n布塔雷利\n您正在里头，先生。\n迭戈\n店主在家吗？\n布塔雷利\n您正在跟他说话。\n迭戈\n您就是布塔雷利？\n布塔雷利\n正是。", highlight_zh: ["月桂客栈"], translation: "own", status: "draft", checked: "Spanish Wikisource, Don Juan Tenorio (1844)/1, 2026-11-22" },
  { id: "ryl-1", book_id: "rimas-y-leyendas", place_ids: ["es-san-juan-duero"], location: "Legend: The Mount of Souls", location_zh: "传说《亡魂山》", text_orig: "—Ese monte que hoy llaman de las Ánimas, pertenecía á los Templarios, cuyo convento ves allí á la margen del río. Los Templarios eran guerreros y religiosos á la vez.", highlight_orig: ["monte que hoy llaman de las Ánimas"], text_en: "'That mountain they now call the Mount of Souls belonged to the Templars, whose monastery you see there on the bank of the river. The Templars were warriors and monks at once.'", highlight_en: ["the Mount of Souls"], text_zh: "“那座如今叫做亡魂山的山，从前属于圣殿骑士团，他们的修道院你看就在那边河岸上。圣殿骑士既是武士，又是修士。”", highlight_zh: ["亡魂山"], translation: "own", status: "draft", checked: "Spanish Wikisource, El monte de las ánimas ('ios', a misread 'los', corrected), 2026-11-22" },
  { id: "pep-1", book_id: "pepita-jimenez", place_ids: ["es-cabra"], location: "Part I, letter of 22 March", location_zh: "第一部，3 月 22 日的信", text_orig: "Querido tío y venerado maestro: Hace cuatro días que llegué con toda felicidad a este lugar de mi nacimiento, donde he hallado bien de salud a mi padre, al señor vicario y a los amigos y parientes.\n…\nComo salí de aquí tan niño y he vuelto hecho un hombre, es singular la impresión que me causan todos estos objetos que guardaba en la memoria. Todo me parece más chico, mucho más chico; pero también más bonito que el recuerdo que tenía. La casa de mi padre, que en mi imaginación era inmensa, es sin duda una gran casa de un rico labrador; pero más pequeña que el Seminario. Lo que ahora comprendo y estimo mejor es el campo de por aquí. Las huertas, sobre todo, son deliciosas.", highlight_orig: ["este lugar de mi nacimiento"], text_en: "Dear uncle and revered master: Four days ago I arrived safe and well in this place where I was born, and found my father, the vicar, and my friends and relations in good health.\n…\nAs I left here so young and have come back a man, all these things I kept in my memory make a strange impression on me. Everything seems smaller to me, much smaller, but also prettier than I remembered it. My father's house, which in my imagination was immense, is no doubt a large house for a rich farmer, but smaller than the Seminary. What I now understand and value more is the countryside round here. The orchards above all are delightful.", highlight_en: ["this place where I was born"], text_zh: "亲爱的叔叔、可敬的老师：四天前我平安回到了我出生的这个地方，父亲、副本堂神父和亲友们都身体安好。\n…\n我离开这里时还那么小，如今长大成人回来，记忆中保存的这一切东西给我一种奇特的感觉。一切都显得小了，小了许多，却也比记忆中更美。父亲的房子在我想象里大得无边，其实不过是个富裕农户的大宅，比神学院小。我现在更懂得、也更珍惜的是这一带的田野。尤其是那些果园，真是可爱极了。", highlight_zh: ["我出生的这个地方"], translation: "own", status: "draft", checked: "Spanish Wikisource, Pepita Jiménez/Capítulo I, 2026-11-22" },
  { id: "tra-1", book_id: "trafalgar-galdos", place_ids: ["es-trafalgar"], location: "Chapter 1", location_zh: "第一章", text_orig: "A este sentimiento consagré mi edad viril y a él consagro esta faena de mis últimos años, poniéndole por genio tutelar o ángel custodio de mi existencia escrita, ya que lo fue de mi existencia real. Muchas cosas voy a contar. ¡Trafalgar, Bailén, Madrid, Zaragoza, Gerona, Arapiles!... De todo esto diré alguna cosa, si no os falta la paciencia. Mi relato no será tan bello como debiera, pero haré todo lo posible para que sea verdadero.", highlight_orig: ["Trafalgar"], text_en: "To this feeling I devoted my manhood, and to it I devote this labour of my last years, setting it as the guardian spirit or angel of my written life, since it was that of my real one. I have many things to tell. Trafalgar, Bailén, Madrid, Zaragoza, Gerona, Arapiles!... Of all this I shall say something, if your patience does not fail. My story will not be as fine as it should be, but I shall do all I can to make it true.", highlight_en: ["Trafalgar"], text_zh: "我把壮年献给了这种感情，如今又把晚年的这份工作献给它，让它做我这部笔下人生的守护神或护卫天使，因为它也曾是我真实人生的守护者。我要讲的事情很多。特拉法尔加、拜伦、马德里、萨拉戈萨、赫罗纳、阿拉皮莱斯！……这一切我都要讲一些，只要你们有耐心。我的叙述不会像应有的那样美，但我会尽力让它真实。", highlight_zh: ["特拉法尔加"], translation: "own", status: "draft", checked: "Spanish Wikisource, Trafalgar/1; the page's line ends inside the paragraph joined, 2026-11-22" },
  { id: "fyj-1", book_id: "fortunata-y-jacinta", place_ids: ["es-cava-san-miguel"], location: "Part I, chapter 3, section 3", location_zh: "第一部第三章第三节", text_orig: "Vivía Plácido en la Cava de San Miguel. Su casa era una de las que forman el costado occidental de la Plaza Mayor, y como el basamento de ellas está mucho más bajo que el suelo de la Plaza, tienen una altura imponente y una estribación formidable, a modo de fortaleza. El piso en que el tal vivía era cuarto por la Plaza y por la Cava séptimo. No existen en Madrid alturas mayores, y para vencer aquellas era forzoso apechugar con ciento veinte escalones, todos de piedra, como decía Plácido con orgullo, no pudiendo ponderar otra cosa de su domicilio.", highlight_orig: ["Cava de San Miguel"], text_en: "Plácido lived in the Cava de San Miguel. His house was one of those that form the western side of the Plaza Mayor, and as their foundations lie much lower than the level of the square, they are of imposing height, with formidable buttresses, like a fortress. The flat he lived in was the fourth floor on the Plaza side and the seventh on the Cava side. There are no greater heights in Madrid, and to overcome them one had to tackle a hundred and twenty steps, all of stone, as Plácido said with pride, having nothing else to boast of in his home.", highlight_en: ["Cava de San Miguel"], text_zh: "普拉西多住在圣米格尔坑道街。他的房子是构成马约尔广场西侧的那排房子之一；这些房子的地基比广场地面低得多，所以高得吓人，墙基又粗又厚，像座堡垒。他住的那一层，从广场这边算是四楼，从坑道街那边算是七楼。马德里再没有比这更高的楼了；要爬上去，得硬着头皮走一百二十级台阶，“全是石头的”，普拉西多骄傲地说，因为他的住处再没有别的可夸了。", highlight_zh: ["圣米格尔坑道街"], translation: "own", status: "draft", checked: "Spanish Wikisource, Fortunata y Jacinta: 1.03.03, 2026-11-22" },
  { id: "fyj-2", book_id: "fortunata-y-jacinta", place_ids: ["es-cava-san-miguel"], location: "Part I, chapter 3, section 4", location_zh: "第一部第三章第四节", text_orig: "-¿Vive aquí -le preguntó- el Sr. de Estupiñá?\n-¿D. Plácido?... en lo más último de arriba -contestó la joven, dando algunos pasos hacia fuera.\nY Juanito pensó: «Tú sales para que te vea el pie. Buena bota»... Pensando esto, advirtió que la muchacha sacaba del mantón una mano con mitón encarnado y que se la llevaba a la boca. La confianza se desbordaba del pecho del joven Santa Cruz, y no pudo menos de decir:\n-¿Qué come usted, criatura?\n-¿No lo ve usted? -replicó mostrándoselo- Un huevo.\n-¡Un huevo crudo!", highlight_orig: ["en lo más último de arriba"], text_en: "'Does Señor Estupiñá live here?' he asked her.\n'Don Plácido?... right at the very top,' the girl answered, taking a few steps out.\nAnd Juanito thought: 'You're coming out so I'll see your foot. A fine boot'... Thinking this, he noticed that the girl drew from her shawl a hand in a red mitten and raised it to her mouth. The young Santa Cruz's familiarity overflowed his chest, and he could not help saying:\n'What are you eating, child?'\n'Can't you see?' she retorted, showing it to him. 'An egg.'\n'A raw egg!'", highlight_en: ["right at the very top"], text_zh: "“埃斯图皮尼亚先生住在这儿吗？”他问她。\n“唐普拉西多？……在最顶上那层，”姑娘答道，一边往外走了几步。\n胡安尼托心想：“你走出来，是要让我看你的脚。好一双靴子。”……这么想着，他发觉姑娘从披肩里伸出一只戴红色露指手套的手，送到嘴边。年轻的圣克鲁斯心里的随便劲儿再也按捺不住，忍不住说：\n“你在吃什么呀，小家伙？”\n“您没看见吗？”她把东西亮给他看，“一个鸡蛋。”\n“一个生鸡蛋！”", highlight_zh: ["最顶上那层"], translation: "own", status: "draft", checked: "Spanish Wikisource, Fortunata y Jacinta: 1.03.04, 2026-11-22" },
  { id: "reg-1", book_id: "la-regenta", place_ids: ["es-oviedo-cathedral"], location: "Chapter 1", location_zh: "第一章", text_orig: "La heroica ciudad dormía la siesta. El viento Sur, caliente y perezoso, empujaba las nubes blanquecinas que se rasgaban al correr hacia el Norte.\n…\nVetusta, la muy noble y leal ciudad, corte en lejano siglo, hacía la digestión del cocido y de la olla podrida, y descansaba oyendo entre sueños el monótono y familiar zumbido de la campana de coro, que retumbaba allá en lo alto de la esbelta torre en la Santa Basílica.", highlight_orig: ["la esbelta torre en la Santa Basílica"], text_en: "The heroic city was taking its siesta. The south wind, hot and lazy, pushed along the whitish clouds, which tore apart as they ran north.\n…\nVetusta, the most noble and loyal city, a royal court in a distant century, was digesting its stew and its olla podrida, and resting as it listened, half asleep, to the monotonous and familiar hum of the choir bell, which boomed high up in the slender tower of the Holy Basilica.", highlight_en: ["the slender tower of the Holy Basilica"], text_zh: "英雄的城市正在午睡。南风又热又懒，推着灰白的云朵，云朵往北跑着跑着就撕裂了。\n…\n维图斯塔，这座极高贵、极忠诚的城市，遥远的某个世纪里曾是宫廷所在，此刻正在消化炖菜和杂烩锅，半睡半醒地听着唱诗钟那单调而熟悉的嗡嗡声，那钟声在圣殿主教座堂细长的塔楼高处回荡。", highlight_zh: ["圣殿主教座堂细长的塔楼"], translation: "own", status: "draft", checked: "Spanish Wikisource, La Regenta/Capítulo I, 2026-11-22" },
  { id: "ins-1", book_id: "insolacion", place_ids: ["es-san-isidro"], location: "Chapter 4", location_zh: "第四章", text_orig: "Don Diego, que en el coche se me figuraba reservado y tristón, se volvió muy dicharachero desde que andábamos por San Isidro, justificando su fama de buena sombra. Sujetando bien mi brazo para que las mareas de gente no nos separasen, él no perdía ripio, y cada pormenor de los tinglados famosos le daba pretexto para un chiste, que muchas veces no era tal sino en virtud del tono y acento con que lo decía, porque es indudable que si se escribiesen las ocurrencias de los andaluces, no resultarían tan graciosas, ni la mitad, de lo que parecen en sus labios; al sonsonete, al ceceíllo y a la prontitud en responder, se debe la mayor parte del salero.\nLo peor fue que como allí no había más personas regulares que nosotros, y Pacheco se metía con todo el mundo y a todo el mundo daba cuerda, nos rodeó la canalla de mendigos, fenómenos, chiquillos harapientos, gitanas, buñoleras y vendedoras. El impulso de mi acompañante era comprar cuanto veía, desde los escapularios hasta los botijos, hasta que me cuadré.", highlight_orig: ["San Isidro"], text_en: "Don Diego, who in the carriage had seemed to me reserved and rather glum, became very talkative once we were walking about San Isidro, living up to his name for charm. Holding my arm firmly so that the tides of people would not separate us, he missed nothing, and every detail of the famous stalls gave him an excuse for a joke, which often was one only by virtue of the tone and accent he said it in; for it is certain that if the sayings of Andalusians were written down they would not be half as funny as they sound on their lips: to the lilt, the little lisp and the quickness of reply is owed most of their wit.\nThe worst of it was that, as there were no respectable people there but ourselves, and Pacheco took on everyone and gave everyone rope, we were surrounded by a rabble of beggars, freaks, ragged children, gypsy women, fritter-sellers and hawkers. My companion's impulse was to buy everything he saw, from scapulars to water jugs, until I put my foot down.", highlight_en: ["San Isidro"], text_zh: "唐迭戈在马车里显得拘谨、有点闷闷不乐，可我们一走进圣伊西德罗，他就变得妙语连珠，不愧是出了名的有趣人。他紧紧挽着我的胳膊，免得人潮把我们冲散，什么也不放过，那些出名的货棚每一处细节都能让他找到由头说个笑话。其实很多笑话之所以好笑，全凭他说话的腔调和口音；因为可以肯定，安达卢西亚人的妙语要是写下来，连说出口时一半的趣味都没有：他们的风趣，大半来自那抑扬的语调、那一点点咬舌音和应答的敏捷。\n最糟的是，那里除了我们俩再没有体面人，而帕切科又跟谁都搭话、跟谁都逗乐，于是一群乞丐、畸形人、衣衫褴褛的孩子、吉卜赛女人、卖油炸饼的和小贩把我们团团围住。我的同伴见什么就想买什么，从护身圣牌到水罐，直到我坚决拦住了他。", highlight_zh: ["圣伊西德罗"], translation: "own", status: "draft", checked: "Spanish Wikisource, Insolación/04, 2026-11-22" },
  { id: "bar-1", book_id: "la-barraca", place_ids: ["es-tribunal-aguas"], location: "Chapter 4", location_zh: "第四章", text_orig: "Era jueves, y, según una costumbre que databa de siglos, el Tribunal de las Aguas iba a reunirse en la puerta de los Apóstoles de la catedral de Valencia.\nEl reloj de la torre llamada el Miguelete señalaba poco más de las diez, y los huertanos juntábanse a corrillos o tomaban asiento en los bordes del tazón de la fuente que adorna la plaza, formando en torno al vaso una animada guirnalda de mantas azules y blancas, pañuelos rojos y amarillos o faldas de indiana de colores oscuros.", highlight_orig: ["el Tribunal de las Aguas", "la puerta de los Apóstoles"], text_en: "It was Thursday, and, by a custom that went back centuries, the Water Tribunal was about to sit at the Apostles' Door of Valencia Cathedral.\nThe clock on the tower called the Miguelete showed a little after ten, and the farmers of the huerta gathered in knots or sat on the rim of the basin of the fountain that adorns the square, forming round the bowl a lively garland of blue and white blankets, red and yellow kerchiefs, and dark-coloured print skirts.", highlight_en: ["the Water Tribunal", "the Apostles' Door"], text_zh: "那天是星期四，按照沿袭了几百年的老规矩，水法庭要在瓦伦西亚大教堂的使徒门前开庭。\n那座叫做米格莱特的钟楼上，时钟刚过十点，菜农们三五成群地聚着，或者坐在装点广场的那座喷泉的池沿上，在水池四周围成一圈热闹的花环：蓝白两色的毯子，红黄两色的头巾，深色的印花布裙子。", highlight_zh: ["水法庭", "使徒门"], translation: "own", status: "draft", checked: "Spanish Wikisource, La barraca/IV, 2026-11-22" },
  { id: "cyb-1", book_id: "canas-y-barro", place_ids: ["es-el-palmar"], location: "Chapter 1, opening", location_zh: "第一章开篇", text_orig: "Como todas las tardes, la barca-correo anunció su llegada al Palmar con varios toques de bocina.\nEl barquero, un hombrecillo enjuto, con una oreja amputada, iba de puerta en puerta recibiendo encargos para Valencia, y al llegar á los espacios abiertos en la única calle del pueblo, soplaba de nuevo en la bocina para avisar su presencia á las barracas desparramadas en el borde del canal. Una nube de chicuelos casi desnudos seguía al barquero con cierta admiración. Les infundía respeto el hombre que cruzaba la Albufera cuatro veces al día, llevándose á Valencia la mejor pesca del lago y trayendo de allá los mil objetos de una ciudad misteriosa y fantástica para aquellos chiquitines criados en una isla de cañas y barro.", highlight_orig: ["al Palmar", "una isla de cañas y barro"], text_en: "As every afternoon, the mail boat announced its arrival at El Palmar with several blasts of its horn.\nThe boatman, a scrawny little man with one ear cut off, went from door to door taking orders for Valencia, and on reaching the open spaces in the village's only street he blew his horn again to let the cabins scattered along the edge of the canal know he was there. A swarm of almost naked urchins followed the boatman with a certain admiration. They were awed by the man who crossed the Albufera four times a day, taking the best fish of the lake to Valencia and bringing back from there the thousand things of a city that was mysterious and fantastic to those little ones raised on an island of reeds and mud.", highlight_en: ["El Palmar", "an island of reeds and mud"], text_zh: "像每天下午一样，邮船吹响几声号角，宣告它到了帕尔马尔。\n船夫是个干瘦的小个子，缺了一只耳朵。他挨家挨户地收捎往瓦伦西亚的东西，走到村里唯一那条街的空地上，又吹起号角，告诉散落在水渠边上的茅屋他来了。一群几乎光着身子的孩子带着几分崇拜跟在船夫后面。他们敬畏这个一天四趟渡过阿尔武费拉湖的人：他把湖里最好的鱼送到瓦伦西亚，又从那里带回千百样东西；对这些在芦苇与泥沼之岛上长大的小家伙来说，那是一座神秘而奇幻的城市。", highlight_zh: ["帕尔马尔", "芦苇与泥沼之岛"], translation: "own", status: "draft", checked: "Spanish Wikisource, Cañas y barro/I, 2026-11-22" },
  { id: "cdc-1", book_id: "campos-de-castilla", place_ids: ["es-espino-soria"], location: "'To a Dry Elm', lines 1–8", location_zh: "《致一棵枯榆》第 1–8 行", text_orig: "Al olmo viejo, hendido por el rayo\ny en su mitad podrido,\ncon las lluvias de abril y el sol de mayo\nalgunas hojas verdes le han salido.\n¡El olmo centenario en la colina\nque lame el Duero! Un musgo amarillento\nle mancha la corteza blanquecina\nal tronco carcomido y polvoriento.", highlight_orig: ["El olmo centenario en la colina", "que lame el Duero"], text_en: "On the old elm, split by lightning\nand half rotten,\nwith the April rains and the May sun\na few green leaves have come out.\nThe hundred-year-old elm on the hill\nthat the Duero laps! A yellowish moss\nstains its whitish bark,\nthe trunk worm-eaten and dusty.", highlight_en: ["The hundred-year-old elm on the hill", "that the Duero laps"], text_zh: "这棵老榆树，被雷电劈开，\n一半已经朽烂，\n四月的雨，五月的阳光，\n竟让它长出了几片绿叶。\n这棵百年老榆，长在\n杜埃罗河轻舔的山冈上！一层黄苔\n沾污了它灰白的树皮，\n那树干已被虫蛀，蒙满尘土。", highlight_zh: ["百年老榆", "杜埃罗河轻舔的山冈"], translation: "own", status: "draft", checked: "Spanish Wikisource, A un olmo seco, 2026-11-22" },
  { id: "nie-1", book_id: "niebla", place_ids: ["es-unamuno-house"], location: "Chapter 31", location_zh: "第三十一章", text_orig: "Emprendió, pues, un viaje acá, a Salamanca, donde hace más de veinte años vivo, para visitarme.\nCuando me anunciaron su visita sonreí enigmáticamente y le mandé pasar a mi despacho-librería. Entró en él como un fantasma, miró a un retrato mío al óleo que allí preside a los libros de mi librería, y a una seña mía se sentó, frente a mí.", highlight_orig: ["Salamanca", "mi despacho-librería"], text_en: "So he set out on a journey here, to Salamanca, where I have lived for more than twenty years, to visit me.\nWhen his visit was announced I smiled enigmatically and had him shown into my study-library. He came in like a ghost, looked at an oil portrait of me that presides there over the books of my library, and at a sign from me sat down, facing me.", highlight_en: ["Salamanca", "my study-library"], text_zh: "于是他启程来到这里，来到萨拉曼卡——我在这里已经住了二十多年——来拜访我。\n听说他来访，我神秘地一笑，叫人领他到我的书房兼藏书室。他像个幽灵似的走进来，看了一眼那幅挂在那里、俯视着我满屋藏书的我的油画肖像，然后在我示意下，在我对面坐下。", highlight_zh: ["萨拉曼卡", "书房兼藏书室"], translation: "own", status: "draft", checked: "Spanish Wikisource, Niebla/XXXI, 2026-11-22" },
  { id: "smb-1", book_id: "san-manuel-bueno", place_ids: ["es-sanabria"], location: "Ángela comes home", location_zh: "安赫拉回到村里", text_orig: "Pasé en el colegio unos cinco años, que ahora se me pierden como un sueño de madrugada en la lejanía del recuerdo, y a los quince volvía a mi Valverde de Lucerna. Ya toda ella era Don Manuel; Don Manuel con el lago y con la montaña. Llegué ansiosa de conocerle, de ponerme bajo su protección, de que él me marcara el sendero de mi vida.", highlight_orig: ["Valverde de Lucerna", "con el lago y con la montaña"], text_en: "I spent some five years at the school, which now fade from me like a dream at dawn in the distance of memory, and at fifteen I came back to my Valverde de Lucerna. By then it was all Don Manuel; Don Manuel with the lake and with the mountain. I arrived eager to know him, to put myself under his protection, for him to mark out the path of my life.", highlight_en: ["Valverde de Lucerna", "with the lake and with the mountain"], text_zh: "我在寄宿学校待了大约五年，如今那几年在记忆的远处，像黎明时的一个梦一样渐渐模糊。十五岁那年，我回到了我的巴尔韦德-德卢塞尔纳。那时，整个村子已经全是堂曼努埃尔了；堂曼努埃尔和湖，和山。我满心渴望认识他，投到他的庇护之下，请他为我指出人生的道路。", highlight_zh: ["巴尔韦德-德卢塞尔纳", "和湖，和山"], translation: "own", status: "draft", checked: "Spanish Wikisource, San Manuel Bueno, mártir, 2026-11-22" },
  { id: "lub-1", book_id: "luces-de-bohemia", place_ids: ["es-callejon-gato"], location: "Scene 12", location_zh: "第十二场", text_orig: "MAX: Los ultraístas son unos farsantes. El esperpentismo lo ha inventado Goya. Los héroes clásicos han ido a pasearse en el callejón del Gato.\nDON LATINO: ¡Estás completamente curda!\nMAX: Los héroes clásicos reflejados en los espejos cóncavos dan el Esperpento. El sentido trágico de la vida española sólo puede darse con una estética sistemáticamente deformada.", highlight_orig: ["el callejón del Gato"], text_en: "MAX: The ultraists are a bunch of frauds. Esperpentism was invented by Goya. The classical heroes have gone for a stroll in the Callejón del Gato.\nDON LATINO: You're completely sozzled!\nMAX: The classical heroes reflected in concave mirrors give the Esperpento. The tragic sense of Spanish life can only be rendered through a systematically deformed aesthetic.", highlight_en: ["the Callejón del Gato"], text_zh: "马克斯：极端主义者都是些骗子。荒诞剧是戈雅发明的。古典英雄们都跑到猫巷去散步了。\n唐拉蒂诺：你完全喝醉了！\n马克斯：古典英雄映在凹面镜里，就成了荒诞剧。西班牙生活的悲剧意味，只有用一种系统地变形的美学才能表现出来。", highlight_zh: ["猫巷"], translation: "own", status: "draft", checked: "Spanish Wikisource, Luces de bohemia/Escena duodécima, 2026-11-22" },
  { id: "cba-1", book_id: "casa-de-bernarda-alba", place_ids: ["es-valderrubio"], location: "Act I", location_zh: "第一幕", text_orig: "Bernarda: Pues busca otro, que te hará falta. En ocho años que dure el luto no ha de entrar en esta casa el viento de la calle. Haceros cuenta que hemos tapiado con ladrillos puertas y ventanas. Así pasó en casa de mi padre y en casa de mi abuelo.", highlight_orig: ["esta casa"], text_en: "Bernarda: Then find another, for you'll need it. In the eight years the mourning lasts, no wind from the street is to come into this house. Think of it as if we had bricked up the doors and windows. That is how it was in my father's house and in my grandfather's.", highlight_en: ["this house"], text_zh: "贝尔纳达：那就去另找一把，你会用得着的。守丧的这八年里，街上的风不许吹进这个家。你们就当我们已经用砖把门窗都砌死了。我父亲家是这样，我祖父家也是这样。", highlight_zh: ["这个家"], translation: "own", status: "draft", checked: "Spanish Wikisource, La casa de Bernarda Alba/Acto I, 2026-11-22" },
  { id: "htc-1", book_id: "homage-to-catalonia", place_ids: ["es-poliorama"], location: "Chapter 10", location_zh: "第十章", text_en: "Immediately opposite there was a cinematograph, called the Poliorama, with a museum above it, and at the top, high above the general level of the roofs, a small observatory with twin domes. The domes commanded the street, and a few men posted up there with rifles could prevent any attack on the P.O.U.M. buildings.", highlight_en: ["Poliorama"], text_zh: "正对面是一家电影院，叫波利奥拉玛，楼上是一座博物馆，顶上高出周围一片屋顶的地方，有一座带两个圆顶的小天文台。这两个圆顶俯瞰着整条街，派几个人带着步枪守在上面，就能挡住对马统工党大楼的任何进攻。", highlight_zh: ["波利奥拉玛"], translation: "original", status: "draft", checked: "Project Gutenberg Australia eBook 0201111h, chapter 10, 2026-11-22" }
];
